import { MakeLogicType, actions, kea, listeners, path, reducers, selectors } from 'kea'
import { urlToAction } from 'kea-router'
import posthog from 'posthog-js'

import { Scene } from 'scenes/sceneTypes'
import { urls } from 'scenes/urls'

import { Breadcrumb, IntegrationKind } from '~/types'

import { destinationTypeLabel } from '../../shared/components/DestinationIcon'
import { WAREHOUSE_DESTINATIONS } from '../../shared/destinations/destinationDefinitions'
import type { WarehouseDestinationDefinition } from '../../shared/destinations/types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface destinationConnectSceneLogicValues {
    breadcrumbs: Breadcrumb[]
    destinationDefinition: WarehouseDestinationDefinition | null
    integrationId: number | null
    isModalOpen: boolean
    kind: string | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface destinationConnectSceneLogicActions {
    setIntegrationId: (integrationId: number) => {
        integrationId: number
    }
    setKind: (kind: string | null) => {
        kind: string | null
    }
    setModalOpen: (open: boolean) => {
        open: boolean
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface destinationConnectSceneLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        destinationDefinition: (kind: string | null) => WarehouseDestinationDefinition | null
        breadcrumbs: (destinationDefinition: WarehouseDestinationDefinition | null) => Breadcrumb[]
    }
}

export type destinationConnectSceneLogicType = MakeLogicType<
    destinationConnectSceneLogicValues,
    destinationConnectSceneLogicActions,
    Record<string, any>,
    destinationConnectSceneLogicMeta
>

export const destinationConnectSceneLogic = kea<destinationConnectSceneLogicType>([
    path(['products', 'dataWarehouse', 'destinationConnectSceneLogic']),
    actions({
        setKind: (kind: string | null) => ({ kind }),
        setModalOpen: (open: boolean) => ({ open }),
        setIntegrationId: (integrationId: number) => ({ integrationId }),
    }),
    reducers({
        kind: [
            null as string | null,
            {
                setKind: (_, { kind }) => kind,
            },
        ],
        isModalOpen: [
            true,
            {
                setKind: () => true,
                setModalOpen: (_, { open }) => open,
            },
        ],
        integrationId: [
            null as number | null,
            {
                setKind: () => null,
                setIntegrationId: (_, { integrationId }) => integrationId,
            },
        ],
    }),
    selectors({
        destinationDefinition: [
            (s) => [s.kind],
            (kind: string | null): WarehouseDestinationDefinition | null =>
                kind
                    ? (Object.values(WAREHOUSE_DESTINATIONS).find((definition) =>
                          definition.integrationKinds.includes(kind as IntegrationKind)
                      ) ?? null)
                    : null,
        ],
        breadcrumbs: [
            (s) => [s.destinationDefinition],
            (destinationDefinition: WarehouseDestinationDefinition | null): Breadcrumb[] => [
                {
                    key: Scene.WarehouseDestinations,
                    name: 'Warehouse destinations',
                    path: urls.warehouseDestinations(),
                    iconType: 'warehouse_destination',
                },
                {
                    key: Scene.WarehouseDestinationConnect,
                    name: destinationDefinition
                        ? `Connect ${destinationTypeLabel(destinationDefinition.type)}`
                        : 'Connect destination',
                    iconType: 'warehouse_destination',
                },
            ],
        ],
    }),
    listeners(({ values }) => ({
        setKind: () => {
            if (values.destinationDefinition) {
                posthog.capture('warehouse destination connect page viewed', {
                    integration_kind: values.kind,
                    destination_type: values.destinationDefinition.type,
                })
            }
        },
        setIntegrationId: () => {
            posthog.capture('warehouse destination connection saved', {
                integration_kind: values.kind,
                destination_type: values.destinationDefinition?.type,
            })
        },
    })),
    urlToAction(({ actions, values }) => ({
        [urls.warehouseDestinationConnect()]: (_, searchParams) => {
            // A hash change (the side panel opening) runs this again, and a reset would hide the saved id.
            const kind = searchParams.kind ?? null
            if (kind !== values.kind) {
                actions.setKind(kind)
            }
        },
    })),
])
